insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0200','civics','Local government','medium','classic','What is a municipality primarily responsible for?','["Local public services and administration","National defense alone","Printing national currency","Foreign treaties"]'::jsonb,'Local public services and administration','Municipal governments commonly provide and manage services within a city or town.',10,2,array['local government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0201','civics','Rights','easy','classic','What does freedom of expression generally protect?','["The ability to communicate ideas subject to lawful limits","A right to harm others","Freedom from all consequences","Only government publications"]'::jsonb,'The ability to communicate ideas subject to lawful limits','Freedom of expression protects seeking, receiving, and sharing information and ideas, while law may impose limited restrictions.',10,2,array['rights'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0202','civics','Accountability','medium','classic','Why are government audits conducted?','["To examine use of public resources","To select sports teams","To set private passwords","To predict earthquakes"]'::jsonb,'To examine use of public resources','Public audits check whether funds and operations comply with rules and perform as reported.',10,2,array['accountability'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0203','civics','India','easy','classic','What is the minimum voting age for Indian general elections?','["18 years","16 years","21 years","25 years"]'::jsonb,'18 years','The Constitution provides adult suffrage from age 18 for eligible citizens.',10,2,array['india'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0204','civics','Rule of law','medium','classic','What does equality before the law mean?','["The law applies without arbitrary privilege","Every person receives the same income","All court cases have the same outcome","No laws may ever change"]'::jsonb,'The law applies without arbitrary privilege','Equality before law rejects arbitrary legal privilege and requires equal legal protection.',10,2,array['rule of law'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0205','civics','Public participation','easy','classic','What is a petition?','["A formal request signed or submitted to an authority","A private bank loan","A criminal sentence","An election result"]'::jsonb,'A formal request signed or submitted to an authority','A petition asks a public body or other authority to take or reconsider action.',10,2,array['public participation'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0206','economics','Basics','easy','classic','What is scarcity in economics?','["Limited resources relative to wants","An unlimited supply of every good","A fall in temperature","A type of bank account"]'::jsonb,'Limited resources relative to wants','Scarcity means resources are limited while human wants exceed what can be produced.',10,2,array['basics'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0207','economics','Markets','easy','classic','What usually happens to quantity demanded when price rises, other things equal?','["It decreases","It always doubles","It becomes unlimited","It equals supply automatically"]'::jsonb,'It decreases','The law of demand describes an inverse relationship between price and quantity demanded, holding other factors constant.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0208','economics','Money','easy','classic','What is inflation?','["A sustained rise in the general price level","A fall in every wage","An increase in product size","A single shop changing one price"]'::jsonb,'A sustained rise in the general price level','Inflation is a broad, sustained increase in prices that reduces money’s purchasing power.',10,2,array['money'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0209','economics','Trade','medium','classic','What is an export?','["A good or service sold to another country","A product bought from another country","A domestic tax bill","Money stored at home"]'::jsonb,'A good or service sold to another country','Exports are domestically produced goods or services sold abroad.',10,2,array['trade'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0210','economics','Production','medium','classic','What is opportunity cost?','["The value of the best alternative forgone","The printed price of every choice","A tax refunded immediately","The total money in a bank"]'::jsonb,'The value of the best alternative forgone','Choosing one option means giving up the benefit of the next best alternative.',10,2,array['production'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0211','economics','Banking','easy','classic','What does a commercial bank commonly pay on eligible deposits?','["Interest","Rent","Tariff","Dividend from government"]'::jsonb,'Interest','Banks may pay depositors interest in return for holding their funds.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0212','economics','Markets','medium','classic','What is equilibrium price in a simple competitive market model?','["The price where quantity supplied equals quantity demanded","The highest legal price in every country","A price selected at random","The cost of producing one unit only"]'::jsonb,'The price where quantity supplied equals quantity demanded','At equilibrium, planned purchases and planned sales are equal.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0213','economics','Government','easy','classic','What is a tax?','["A compulsory payment to government under law","A voluntary shop discount","A private gift","A bank’s password"]'::jsonb,'A compulsory payment to government under law','Taxes are mandatory levies used to finance public activity.',10,2,array['government'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0214','economics','Business cycle','medium','classic','What is a recession commonly associated with?','["A broad decline in economic activity","Permanent zero unemployment","A sudden increase in all resources","A rise in one company’s sales only"]'::jsonb,'A broad decline in economic activity','A recession is a significant, widespread decline in economic activity lasting more than a brief fluctuation.',10,2,array['business cycle'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0215','economics','Labor','easy','classic','What is unemployment?','["People able and seeking work lack jobs","Every worker changes jobs","People choose leisure and seek no work","All students attend school"]'::jsonb,'People able and seeking work lack jobs','Standard measures count people without work who are available for and actively seeking it.',10,2,array['labor'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0216','economics','Trade','medium','classic','What is a tariff?','["A tax on imported goods","A subsidy paid to every consumer","A limit on working hours","A currency note"]'::jsonb,'A tax on imported goods','A tariff is a customs duty imposed on imports.',10,2,array['trade'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0217','economics','Productivity','medium','classic','What does labor productivity measure?','["Output produced per unit of labor input","Total population only","The number of products advertised","The price of imported fuel"]'::jsonb,'Output produced per unit of labor input','Labor productivity compares output with labor hours or workers used.',10,2,array['productivity'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0218','music','Notation','easy','classic','How many lines are in a standard musical staff?','["Five","Four","Six","Eight"]'::jsonb,'Five','Modern Western staff notation uses five horizontal lines.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0219','music','Rhythm','easy','classic','What is a rest in music?','["A notated silence","A repeated melody","A change of instrument","The final concert bow"]'::jsonb,'A notated silence','A rest indicates a measured duration of silence.',10,2,array['rhythm'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0220','music','Pitch','medium','classic','What is an octave?','["The interval between pitches with a two-to-one frequency ratio","Any group of eight musicians","A very soft dynamic only","A rhythm with three beats"]'::jsonb,'The interval between pitches with a two-to-one frequency ratio','Pitches an octave apart are perceived as closely related and have a 2:1 frequency ratio.',10,2,array['pitch'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0221','music','Dynamics','easy','classic','What does forte usually mean?','["Loud","Soft","Slow","Detached"]'::jsonb,'Loud','The Italian dynamic marking forte directs performers to play loudly.',10,2,array['dynamics'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0222','music','Melody','easy','classic','What is a melody?','["A sequence of pitches perceived as a musical line","The physical case of an instrument","Silence between movements only","The speed of a metronome"]'::jsonb,'A sequence of pitches perceived as a musical line','A melody is an organized succession of pitches heard as a coherent line.',10,2,array['melody'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0223','music','Harmony','medium','classic','What is a chord?','["Three or more pitches sounded as a harmonic unit","One beat of silence","A gradual increase in speed","A single drum stroke only"]'::jsonb,'Three or more pitches sounded as a harmonic unit','A chord combines multiple pitches, commonly three or more, as one harmony.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0224','music','Rhythm','medium','classic','What does a 3 over 4 time signature normally indicate?','["Three quarter-note beats per measure","Four measures in three minutes","Three instruments and four singers","A tempo of 34 beats per minute"]'::jsonb,'Three quarter-note beats per measure','Three-four meter groups three quarter-note beats in each bar.',10,2,array['rhythm'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0225','music','Form','easy','classic','What is a chorus in a song?','["A recurring section with repeated music or words","The tuning peg of a guitar","A silent introduction","A single low note"]'::jsonb,'A recurring section with repeated music or words','A chorus returns during a song and often contains its central refrain.',10,2,array['form'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0226','music','Timbre','medium','classic','What does timbre describe?','["The tone color that distinguishes sound sources","Only how fast music is","The written key signature","The number of audience members"]'::jsonb,'The tone color that distinguishes sound sources','Timbre is the sound quality that lets listeners distinguish instruments playing the same pitch.',10,2,array['timbre'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0227','music','Notation','easy','classic','What does a sharp sign do to a note in standard notation?','["Raises it by one semitone","Lowers it by one octave","Doubles its duration","Makes it silent"]'::jsonb,'Raises it by one semitone','A sharp raises the pitch by one chromatic semitone.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0228','music','Ensembles','easy','classic','What is a duet?','["A piece or performance for two musicians","A group of eight singers","A solo without accompaniment","An orchestra conductor"]'::jsonb,'A piece or performance for two musicians','A duet features two performers or musical parts.',10,2,array['ensembles'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0229','music','Tempo','medium','classic','What does accelerando instruct musicians to do?','["Gradually increase the tempo","Gradually become quieter","Repeat from the beginning","Tune down one semitone"]'::jsonb,'Gradually increase the tempo','Accelerando means to speed up gradually.',10,2,array['tempo'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/');
