insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0266','management','Planning','easy','classic','What is the main purpose of setting a SMART objective?','["To make a goal specific and assessable","To remove every deadline","To avoid measuring progress","To assign no owner"]'::jsonb,'To make a goal specific and assessable','SMART criteria make objectives specific, measurable, achievable, relevant, and time-bound.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0267','management','Leadership','medium','classic','What is delegation?','["Assigning responsibility and authority for a task","Avoiding all accountability","Completing every task personally","Removing a task without telling anyone"]'::jsonb,'Assigning responsibility and authority for a task','Delegation entrusts a task and suitable authority while the manager retains overall accountability.',10,2,array['leadership'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0268','management','Projects','easy','classic','What is a project milestone?','["A significant checkpoint or event","Every small daily expense","A permanent job title","An unapproved change"]'::jsonb,'A significant checkpoint or event','A milestone marks important progress or completion in a project schedule.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0269','management','Risk','medium','classic','What is a risk register used for?','["Recording and tracking identified risks","Listing employee birthdays","Replacing the project budget","Writing customer invoices only"]'::jsonb,'Recording and tracking identified risks','A risk register records risks, assessments, owners, and planned responses.',10,2,array['risk'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0270','management','Teams','easy','classic','Why are roles clarified within a team?','["To reduce gaps and duplicated work","To eliminate communication","To guarantee no disagreement","To prevent collaboration"]'::jsonb,'To reduce gaps and duplicated work','Clear roles help people understand responsibilities and coordinate work.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0271','management','Control','medium','classic','What is a key performance indicator?','["A measure linked to an important objective","Any number in a report","A private employee opinion","A company logo"]'::jsonb,'A measure linked to an important objective','A KPI is a defined measure used to track progress toward a critical objective.',10,2,array['control'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0272','management','Decision making','medium','classic','What is a cost-benefit analysis?','["Comparison of expected costs and benefits","A list of costs without outcomes","A review of employee clothing","A method for hiding uncertainty"]'::jsonb,'Comparison of expected costs and benefits','Cost-benefit analysis compares an option’s anticipated gains with its costs.',10,2,array['decision making'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0273','management','Communication','easy','classic','What is active listening?','["Attending, clarifying, and responding to understand","Waiting silently to interrupt","Agreeing with every statement","Reading an unrelated report"]'::jsonb,'Attending, clarifying, and responding to understand','Active listening uses attention, questions, and feedback to understand a speaker.',10,2,array['communication'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0274','management','Quality','medium','classic','What is continuous improvement?','["Ongoing effort to improve processes and outcomes","One large change with no review","Keeping every process unchanged","Inspecting only after failure"]'::jsonb,'Ongoing effort to improve processes and outcomes','Continuous improvement repeatedly identifies and tests ways to improve performance.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0275','management','Change','medium','classic','Why identify stakeholders before a major change?','["To understand who is affected and how to engage them","To avoid all communication","To guarantee unanimous support","To remove the need for planning"]'::jsonb,'To understand who is affected and how to engage them','Stakeholder analysis helps plan communication, participation, and responses to impacts.',10,2,array['change'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0276','management','Time','easy','classic','What does prioritization help a manager do?','["Focus resources on the most important work","Make every task equally urgent","Remove all deadlines","Avoid deciding between tasks"]'::jsonb,'Focus resources on the most important work','Prioritization ranks work by importance, urgency, value, and constraints.',10,2,array['time'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0277','management','Ethics','medium','classic','What is a conflict of interest?','["Personal interests could improperly influence duties","Two employees have different skills","A project has two deadlines","A customer asks a question"]'::jsonb,'Personal interests could improperly influence duties','A conflict exists when personal interests could compromise, or appear to compromise, objective judgment.',10,2,array['ethics'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0278','business','Models','easy','classic','What is a value proposition?','["The benefit offered to a target customer","A list of employee names","A tax return","A building lease only"]'::jsonb,'The benefit offered to a target customer','A value proposition explains why a customer would choose an offering.',10,2,array['models'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0279','business','Customers','easy','classic','What is a target market?','["The customer group a business aims to serve","Every person in the world automatically","Only current employees","Government agencies only"]'::jsonb,'The customer group a business aims to serve','A target market is the defined group most likely to need and buy an offering.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0280','business','Marketing','medium','classic','What are the four Ps in a common marketing mix?','["Product, price, place, and promotion","People, profit, policy, and payroll","Plan, process, patent, and power","Purchase, payment, promise, and proof"]'::jsonb,'Product, price, place, and promotion','The traditional four-P framework covers product, price, place, and promotion.',10,2,array['marketing'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0281','business','Operations','easy','classic','What is inventory?','["Goods and materials held for use or sale","Money owed to a lender only","Employee working hours","A customer complaint"]'::jsonb,'Goods and materials held for use or sale','Inventory includes raw materials, work in progress, and finished goods held by a business.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0282','business','Entrepreneurship','medium','classic','What is a minimum viable product?','["A basic version used to test key assumptions","A product with no useful function","The final product with every feature","A legally required sales quota"]'::jsonb,'A basic version used to test key assumptions','An MVP provides enough value to learn from early users before larger investment.',10,2,array['entrepreneurship'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0283','business','Competition','easy','classic','What is market share?','["A firm’s portion of total market sales","A company’s office floor area","The number of shares one worker owns","A government tax rate"]'::jsonb,'A firm’s portion of total market sales','Market share compares a firm’s sales with total sales in the defined market.',10,2,array['competition'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0284','business','Strategy','medium','classic','What does SWOT analysis examine?','["Strengths, weaknesses, opportunities, and threats","Sales, wages, orders, and taxes","Systems, work, output, and time","Stock, wealth, ownership, and trade"]'::jsonb,'Strengths, weaknesses, opportunities, and threats','SWOT organizes internal strengths and weaknesses and external opportunities and threats.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0285','business','Customers','easy','classic','Why do businesses collect customer feedback?','["To understand needs and improve offerings","To guarantee every review is positive","To replace financial records","To avoid measuring satisfaction"]'::jsonb,'To understand needs and improve offerings','Feedback reveals customer experiences, problems, and unmet needs.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0286','business','Supply chain','medium','classic','What is a supplier?','["A party that provides goods or services to a business","Only the final consumer","A government judge","An employee on leave"]'::jsonb,'A party that provides goods or services to a business','Suppliers provide inputs a business needs to operate or produce.',10,2,array['supply chain'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0287','business','Finance','easy','classic','What is revenue?','["Income earned from ordinary sales or services","Every asset owned by a business","Only cash borrowed from a bank","Profit after every cost"]'::jsonb,'Income earned from ordinary sales or services','Revenue is the gross income generated by normal business activities before expenses.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0288','business','Legal forms','medium','classic','What is limited liability intended to limit?','["Owners’ personal exposure to business debts","The number of customers","Employee working hours","The price of every product"]'::jsonb,'Owners’ personal exposure to business debts','In limited-liability entities, owners generally risk their investment rather than all personal assets, subject to law and exceptions.',10,2,array['legal forms'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0289','business','Ethics','easy','classic','What is corporate social responsibility?','["Considering social and environmental impacts of business","Ignoring every stakeholder except owners","A guarantee of zero environmental impact","A substitute for obeying law"]'::jsonb,'Considering social and environmental impacts of business','CSR describes business responsibility for effects on society and the environment beyond narrow financial results.',10,2,array['ethics'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0290','accounting','Equation','easy','classic','What is the basic accounting equation?','["Assets equal liabilities plus equity","Revenue equals assets plus cash","Expenses equal profit plus inventory","Equity equals revenue plus tax"]'::jsonb,'Assets equal liabilities plus equity','The statement of financial position is based on Assets = Liabilities + Equity.',10,2,array['equation'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0291','accounting','Statements','easy','classic','Which statement reports financial position at a point in time?','["Balance sheet","Income statement","Cash receipt","Sales invoice"]'::jsonb,'Balance sheet','A balance sheet, or statement of financial position, reports assets, liabilities, and equity on a date.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0292','accounting','Statements','medium','classic','What does an income statement report?','["Revenue and expenses over a period","Assets on one date only","Only cash in the bank","Every future budget"]'::jsonb,'Revenue and expenses over a period','The income statement summarizes income, expenses, and profit or loss for a reporting period.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0293','accounting','Bookkeeping','easy','classic','What is a ledger?','["A collection of accounts and their transactions","A list of customer phone numbers","A product catalog","A bank loan agreement"]'::jsonb,'A collection of accounts and their transactions','The ledger classifies transaction entries into individual accounts.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0294','accounting','Accruals','medium','classic','Under accrual accounting, when is revenue generally recognized?','["When earned, not merely when cash arrives","Only when cash is deposited","Whenever a quote is issued","Only at year end"]'::jsonb,'When earned, not merely when cash arrives','Accrual accounting recognizes revenue when the earning obligation is satisfied, subject to applicable standards.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0295','accounting','Assets','easy','classic','What is depreciation?','["Allocating a tangible asset’s depreciable amount over its useful life","Increasing an asset to market price every day","Recording a new bank loan","Paying a cash dividend"]'::jsonb,'Allocating a tangible asset’s depreciable amount over its useful life','Depreciation systematically allocates the cost or depreciable amount of a tangible asset over its useful life.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0296','accounting','Entries','medium','classic','In double-entry bookkeeping, what must every transaction keep in balance?','["Total debits and total credits","Cash and profit only","Sales and inventory quantities","Invoices and receipts by count"]'::jsonb,'Total debits and total credits','Every entry has equal total debit and credit amounts.',10,2,array['entries'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0297','accounting','Liabilities','easy','classic','What is a liability?','["A present obligation expected to require resources","A resource controlled by the business","Income earned from sales","An owner’s personal hobby"]'::jsonb,'A present obligation expected to require resources','A liability is a present obligation arising from past events that is expected to require an outflow of resources.',10,2,array['liabilities'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0298','accounting','Assets','medium','classic','What is accounts receivable?','["Amounts customers owe the business","Amounts the business owes suppliers","Cash paid as wages","Owners’ contributed capital"]'::jsonb,'Amounts customers owe the business','Accounts receivable records credit sales not yet collected from customers.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0299','accounting','Liabilities','medium','classic','What is accounts payable?','["Amounts the business owes suppliers","Amounts customers owe the business","Cash held in a register","Profit retained in equity"]'::jsonb,'Amounts the business owes suppliers','Accounts payable records unpaid obligations for goods or services received from suppliers.',10,2,array['liabilities'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0300','accounting','Inventory','medium','classic','What does cost of goods sold represent?','["Cost of inventory sold during the period","Selling price of all inventory held","Cost of office furniture only","Cash collected from customers"]'::jsonb,'Cost of inventory sold during the period','Cost of goods sold is the carrying cost of inventory recognized when those goods are sold.',10,2,array['inventory'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0301','accounting','Audit','easy','classic','What is the purpose of an independent financial statement audit?','["To provide an opinion on whether statements are fairly presented","To guarantee the business will be profitable","To prepare every sales invoice","To set product prices"]'::jsonb,'To provide an opinion on whether statements are fairly presented','An independent audit obtains evidence and expresses an opinion under the applicable reporting framework.',10,2,array['audit'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0302','commerce','Trade','easy','classic','What is wholesale trade?','["Selling goods in quantity mainly to retailers or businesses","Selling one item only to final consumers","Giving all products away","Trading services only within a household"]'::jsonb,'Selling goods in quantity mainly to retailers or businesses','Wholesalers typically buy and sell in bulk to retailers and other organizations.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0303','commerce','Trade','easy','classic','What is retailing?','["Selling goods or services to final consumers","Producing raw materials only","Lending only to governments","Shipping goods without selling them"]'::jsonb,'Selling goods or services to final consumers','Retailers sell directly to consumers for personal or household use.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0304','commerce','Documents','medium','classic','What is an invoice?','["A document requesting payment for supplied goods or services","A receipt proving payment has always occurred","A company ownership certificate","A customs passport"]'::jsonb,'A document requesting payment for supplied goods or services','An invoice itemizes a sale and states the amount the buyer owes.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0305','commerce','Payments','easy','classic','What is a receipt?','["Evidence that payment was received","A request for a future quote","A list of unpaid taxes only","A transport timetable"]'::jsonb,'Evidence that payment was received','A receipt acknowledges that money or goods have been received.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0306','commerce','Logistics','medium','classic','What is a bill of lading?','["A transport document acknowledging cargo for shipment","A retail price label","An employee wage slip","A product advertisement"]'::jsonb,'A transport document acknowledging cargo for shipment','A carrier issues a bill of lading as evidence of receipt and terms for transported goods.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0307','commerce','Insurance','easy','classic','What is an insurance premium?','["The price paid for insurance coverage","The amount of every covered loss","A guaranteed investment profit","A customs duty"]'::jsonb,'The price paid for insurance coverage','The premium is the amount charged by an insurer for coverage.',10,2,array['insurance'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0308','commerce','Warehousing','medium','classic','Why are goods stored in a warehouse?','["To hold and manage inventory until needed","To eliminate all transport","To avoid counting inventory","To turn every good into cash immediately"]'::jsonb,'To hold and manage inventory until needed','Warehousing protects, organizes, and makes inventory available for distribution.',10,2,array['warehousing'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0309','commerce','E-commerce','easy','classic','What is e-commerce?','["Buying and selling through electronic networks","Only advertising on paper","Transporting goods by ship only","Manufacturing without customers"]'::jsonb,'Buying and selling through electronic networks','E-commerce conducts commercial transactions through websites, apps, and other electronic networks.',10,2,array['e-commerce'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0310','commerce','Trade','medium','classic','What is a trade discount?','["A reduction from list price offered within the distribution channel","Interest charged on a late loan","A tax on imports","A refund after every purchase"]'::jsonb,'A reduction from list price offered within the distribution channel','A trade discount reduces the catalog price, often for resellers or volume purchases.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0311','commerce','Banking','easy','classic','What is working capital commonly calculated as?','["Current assets minus current liabilities","Revenue minus every asset","Cash plus long-term debt","Equity minus sales"]'::jsonb,'Current assets minus current liabilities','Net working capital is commonly defined as current assets less current liabilities.',10,2,array['banking'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0312','commerce','Consumer protection','medium','classic','Why is a return policy important?','["It explains conditions for returning or exchanging purchases","It guarantees every item lasts forever","It replaces product safety law","It sets employee salaries"]'::jsonb,'It explains conditions for returning or exchanging purchases','A clear return policy tells buyers the time limits, conditions, and remedies available.',10,2,array['consumer protection'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0313','commerce','International trade','easy','classic','What is an import?','["A good or service bought from another country","A product sold to another country","A local warehouse transfer","A domestic sales tax"]'::jsonb,'A good or service bought from another country','Imports are foreign-produced goods or services purchased by domestic buyers.',10,2,array['international trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm');
